@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --font-fallback: "Helvetica Neue", Arial, sans-serif;
}

html {
  scroll-behavior: smooth;
}

html,
body {
  background: #fff;
  color: #000;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

/* Site-wide page entrance */
.page-enter {
  position: relative;
  min-height: 100%;
  /*
   * Do not retain the animation's final transform/filter. Either property
   * creates a containing block for fixed descendants, which pushed product
   * drawers and color modals outside the mobile viewport after page load.
   */
  animation: page-enter 480ms cubic-bezier(0.22, 1, 0.36, 1);
}

.page-enter::before {
  content: "";
  pointer-events: none;
  position: absolute;
  inset: 0 auto auto 0;
  z-index: 60;
  width: 100%;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, #3ecf4c 35%, #3ecf4c 65%, transparent 100%);
  transform-origin: left;
  animation: page-accent 620ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes page-enter {
  from {
    opacity: 0;
    transform: translateY(10px);
    filter: blur(2px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes page-accent {
  0% { opacity: 0; transform: scaleX(0); }
  35% { opacity: 1; }
  72% { opacity: 1; transform: scaleX(1); }
  100% { opacity: 0; transform: scaleX(1); }
}

@media (prefers-reduced-motion: reduce) {
  .page-enter,
  .page-enter::before {
    animation: none;
  }
}

/* Premium display headings */
.h-display {
  font-family: var(--font-display, Sora), var(--font-sans, Inter), "Helvetica Neue", Arial, sans-serif;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: -0.03em;
  line-height: 0.92;
}

/* Reveal product actions on hover, touch press, or keyboard focus. */
.product-card-cta {
  opacity: 0;
  transition: opacity 160ms ease, background-color 160ms ease;
}
@media (hover: hover) and (pointer: fine) {
  .product-card:hover .product-card-cta { opacity: 1; }
}
.product-card:active .product-card-cta,
.product-card:focus-visible .product-card-cta,
.product-card:has(:focus-visible) .product-card-cta { opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  .product-card-cta { transition: none; }
}

/* Mobile drawer scroll — hide scrollbar */
.drawer-scroll::-webkit-scrollbar { display: none; }

/* Search overlay responsive visibility */
@media (min-width: 768px) { .so-mobile  { display: none !important; } }
@media (max-width: 767px)  { .so-desktop { display: none !important; } }
@keyframes _spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

/* ── Ecomedia section animations ──────────────────────────────── */
@keyframes ecomedia-float {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  33%       { transform: translateY(-8px) rotate(0.3deg); }
  66%       { transform: translateY(-4px) rotate(-0.2deg); }
}
@keyframes ecomedia-glow-pulse {
  0%, 100% { opacity: 0.08; transform: scale(1); }
  50%       { opacity: 0.18; transform: scale(1.15); }
}
@keyframes ecomedia-fade-up {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes ecomedia-btn-shimmer {
  0%   { background-position: -200% center; }
  100% { background-position: 200% center; }
}
@keyframes ecomedia-slide-in {
  from { opacity: 0; transform: translateX(24px); }
  to   { opacity: 1; transform: translateX(0); }
}

.animate-ecomedia-float    { animation: ecomedia-float 6s ease-in-out infinite; }
.animate-ecomedia-glow     { animation: ecomedia-glow-pulse 4s ease-in-out infinite; }
.animate-ecomedia-fade-up  { animation: ecomedia-fade-up 0.7s cubic-bezier(0.16,1,0.3,1) both; }
.animate-ecomedia-slide-in { animation: ecomedia-slide-in 0.8s cubic-bezier(0.16,1,0.3,1) both; }
.delay-100 { animation-delay: 0.1s; }
.delay-200 { animation-delay: 0.2s; }
.delay-300 { animation-delay: 0.3s; }
.delay-400 { animation-delay: 0.4s; }
.delay-500 { animation-delay: 0.5s; }
.delay-600 { animation-delay: 0.6s; }


/* Mobile drawer stagger animations */
@keyframes drawerFadeUp {
  from { opacity: 0; transform: translateY(18px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Cart icon bounce on add-to-cart */
@keyframes cart-bounce {
  0%   { transform: scale(1); }
  30%  { transform: scale(1.45); }
  55%  { transform: scale(0.88); }
  75%  { transform: scale(1.12); }
  90%  { transform: scale(0.97); }
  100% { transform: scale(1); }
}
.cart-pulse {
  animation: cart-bounce 0.65s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
@keyframes drawerFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}
.drawer-item {
  opacity: 0;
  animation: drawerFadeUp 0.38s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
.drawer-bg {
  opacity: 0;
  animation: drawerFadeIn 0.25s ease forwards;
}

/* Section label — small eyebrow text used across pages */
.label-eyebrow {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.35em;
  color: #a3a3a3;
}

/* Divider accent line used under section titles */
.section-accent {
  display: block;
  width: 40px;
  height: 3px;
  background: #000;
  margin-top: 10px;
}

/* Premium button reset */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #000;
  color: #fff;
  font-weight: 900;
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  padding: 14px 28px;
  transition: background 0.2s, transform 0.1s;
}
.btn-primary:hover { background: #1a1a1a; }
.btn-primary:active { transform: scale(0.97); }

/* Marquee bar */
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
.marquee-track {
  display: inline-flex;
  gap: 0;
  white-space: nowrap;
  animation: marquee 36s linear infinite;
  will-change: transform;
}
.marquee-track[data-pause-on-hover="true"]:hover {
  animation-play-state: paused;
}

/* Keep the mobile wordmark proportional when the action buttons fill the row. */
.storefront-header-logo svg {
  overflow: visible;
}

/* Dark mode disabled. The storefront always uses the light theme. */`r`n`r`n/* Maintenance page follows the selected appearance theme. */
.maintenance-page { min-height: 100dvh; }
/* Also support the app's explicit dark theme attribute/class. */
:is(html.dark, body.dark, [data-theme="dark"]) .storefront-header-logo,
:is(html.dark, body.dark, [data-theme="dark"]) .storefront-header-logo svg {
  color: #ffffff !important;
}
@media (max-width: 399px) {
  .storefront-header-bar {
    padding-inline: 12px;
  }
  .storefront-header-brand {
    gap: 4px;
  }
  .storefront-header-logo {
    width: min(135px, calc(100vw - 232px));
    flex-shrink: 0;
  }
  .storefront-header-logo svg {
    width: 100%;
    height: auto;
  }
  .storefront-header-bar .header-action-button {
    width: 40px;
    flex-basis: 40px;
  }
}

/* Cohesive header action icon system */
.header-action-button {
  position: relative;
  display: inline-flex;
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  align-items: center;
  justify-content: center;
  padding: 0;
  border-radius: 999px;
  color: #404040;
  line-height: 0;
  transition: color 180ms ease, background-color 180ms ease, transform 120ms ease;
}
.header-action-button > svg,
.header-action-button > span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.header-action-button svg {
  display: block;
  width: 24px;
  height: 24px;
  flex: none;
}
.header-action-button:hover {
  background: #f5f5f5;
  color: #050505;
}
.header-action-button:active {
  transform: scale(0.94);
}
.header-action-button:focus-visible {
  outline: 2px solid #111;
  outline-offset: 2px;
}
.header-action-badge {
  position: absolute;
  right: -6px;
  top: -5px;
  z-index: 1;
  display: flex;
  min-width: 16px;
  height: 16px;
  align-items: center;
  justify-content: center;
  border: 2px solid #fff;
  border-radius: 999px;
  background: #3ecf4c;
  padding: 0 3px;
  color: #050505;
  font-size: 8px;
  font-weight: 900;
  line-height: 1;
}

/* Hide scrollbar for horizontal rails */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { scrollbar-width: none; }

/* ── Custom green scrollbar ──────────────────────────────────────── */
html::-webkit-scrollbar {
  width: 8px;
}
html::-webkit-scrollbar-track {
  background: transparent;
}
html::-webkit-scrollbar-thumb {
  background: #3ecf4c;
  background-clip: padding-box;
  border: 2px solid transparent;
  border-radius: 99px;
}
html::-webkit-scrollbar-thumb:hover {
  background: #2db83a;
  background-clip: padding-box;
}
html::-webkit-scrollbar-corner {
  background: transparent;
}

/* Firefox */
html {
  scrollbar-width: thin;
  scrollbar-color: #3ecf4c transparent;
}

/* Keep the page scrollbar color from inheriting into nested scroll areas. */
body {
  scrollbar-color: auto;
}

.eco-chat-scroll {
  scrollbar-width: thin;
  scrollbar-color: #c2cdc5 transparent;
  overscroll-behavior: contain;
}

/* Use custom rounded thumbs without native arrow buttons where supported. */
@supports selector(::-webkit-scrollbar) {
  .eco-chat-scroll {
    scrollbar-width: auto;
    scrollbar-color: auto;
  }

  .eco-chat-scroll::-webkit-scrollbar {
    width: 6px;
    height: 6px;
  }

  .eco-chat-scroll::-webkit-scrollbar-track {
    background: transparent;
    margin-block: 12px;
  }

  .eco-chat-scroll::-webkit-scrollbar-thumb {
    background: #c2cdc5;
    background-clip: padding-box;
    border: 1px solid transparent;
    border-radius: 999px;
  }

  .eco-chat-scroll::-webkit-scrollbar-thumb:hover {
    background-color: #92a398;
  }

  .eco-chat-scroll::-webkit-scrollbar-button {
    display: none;
    width: 0;
    height: 0;
  }

  .eco-chat-scroll::-webkit-scrollbar-corner {
    background: transparent;
  }
}

/* ── Cart attention animations ─────────────────────────────────── */
@keyframes cart-wobble {
  0%          { transform: rotate(0deg) scale(1); }
  10%         { transform: rotate(-14deg) scale(1.15); }
  20%         { transform: rotate(12deg) scale(1.1); }
  30%         { transform: rotate(-10deg) scale(1.05); }
  40%         { transform: rotate(8deg); }
  50%         { transform: rotate(-6deg); }
  60%         { transform: rotate(4deg); }
  70%         { transform: rotate(-2deg); }
  80%, 100%   { transform: rotate(0deg) scale(1); }
}

@keyframes badge-pop {
  0%, 60%  { transform: scale(1); }
  70%      { transform: scale(1.6); }
  80%      { transform: scale(0.9); }
  90%      { transform: scale(1.2); }
  100%     { transform: scale(1); }
}

/* ── Checkout & Order confirmation animations ───────────────────── */
@keyframes check-draw {
  to { stroke-dashoffset: 0; }
}
@keyframes ring-pulse {
  0%   { transform: scale(0.95); opacity: 0.5; }
  100% { transform: scale(1.9);  opacity: 0; }
}
@keyframes fade-up {
  from { opacity: 0; transform: translateY(22px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes pop-scale {
  0%   { transform: scale(0) rotate(-8deg); opacity: 0; }
  65%  { transform: scale(1.12) rotate(2deg); opacity: 1; }
  100% { transform: scale(1) rotate(0deg); opacity: 1; }
}
@keyframes confetti-fall {
  0%   { transform: translateY(-30px) rotate(0deg) scale(1); opacity: 1; }
  80%  { opacity: 0.9; }
  100% { transform: translateY(110vh) rotate(680deg) scale(0.3); opacity: 0; }
}
@keyframes shimmer {
  0%   { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
@keyframes input-focus-in {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}
@keyframes rotate-cw {
  to { transform: rotate(360deg); }
}
@keyframes rotate-ccw {
  to { transform: rotate(-360deg); }
}
@keyframes ray-burst {
  0%   { transform: scaleY(0) translateY(0); opacity: 0; }
  30%  { opacity: 1; }
  100% { transform: scaleY(1) translateY(-48px); opacity: 0; }
}
@keyframes float-up-fade {
  0%   { transform: translateY(0) scale(1); opacity: 1; }
  100% { transform: translateY(-80px) scale(0.4); opacity: 0; }
}
@keyframes sparkle-blink {
  0%, 100% { transform: scale(1) rotate(0deg);   opacity: 0.9; }
  50%       { transform: scale(0.25) rotate(90deg); opacity: 0.1; }
}
@keyframes slide-in-right {
  from { width: 0; }
  to   { width: 100%; }
}
@keyframes bounce-truck {
  0%, 100% { transform: translateX(0); }
  50%       { transform: translateX(5px); }
}
@keyframes glow-breathe {
  0%, 100% { opacity: 0.5; }
  50%       { opacity: 1; }
}
@keyframes count-up-reveal {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

.cart-bag-icon {
  display: inline-block;
  animation: cart-wobble 3s ease-in-out 1.5s infinite;
  transform-origin: top center;
}

.cart-badge {
  animation: badge-pop 3s ease-in-out 1.5s infinite;
  transform-origin: center;
}

/* ── Hero entrance animations ───────────────────────────────────── */
@keyframes hero-fade-up {
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
}
@keyframes hero-line-in {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}
@keyframes hero-ken-burns {
  from { transform: scale(1); }
  to   { transform: scale(1.06); }
}

.hero-image {
  animation: hero-ken-burns 10s ease-out forwards;
}
.hero-eyebrow  { animation: hero-fade-up 0.7s cubic-bezier(0.22,1,0.36,1) 0.2s both; }
.hero-headline { animation: hero-fade-up 0.7s cubic-bezier(0.22,1,0.36,1) 0.38s both; }
.hero-sub      { animation: hero-fade-up 0.7s cubic-bezier(0.22,1,0.36,1) 0.52s both; }
.hero-ctas     { animation: hero-fade-up 0.7s cubic-bezier(0.22,1,0.36,1) 0.66s both; }

@keyframes hero-cta-arrive {
  0% { opacity: 0; transform: translateY(18px) scale(.96); filter: blur(5px); }
  100% { opacity: 1; transform: translateY(0) scale(1); filter: blur(0); }
}

@keyframes hero-cta-shine {
  0%, 58% { transform: translateX(0) skewX(-12deg); opacity: 0; }
  64% { opacity: .9; }
  78%, 100% { transform: translateX(520%) skewX(-12deg); opacity: 0; }
}

@keyframes hero-cta-arrow-nudge {
  0%, 70%, 100% { transform: translateX(0); }
  78% { transform: translateX(5px); }
  86% { transform: translateX(0); }
  92% { transform: translateX(3px); }
}

.hero-cta-row {
  animation: hero-cta-arrive .8s cubic-bezier(.16,1,.3,1) .48s both;
}

.hero-cta-shine {
  animation: hero-cta-shine 5.5s ease-in-out 1.1s infinite;
}

.hero-cta-arrow {
  animation: hero-cta-arrow-nudge 3.2s ease-in-out 1.4s infinite;
}

.hero-cta:hover .hero-cta-shine,
.hero-cta:focus-visible .hero-cta-shine {
  animation: none;
  transform: translateX(520%) skewX(-12deg);
  opacity: .8;
  transition: transform .7s cubic-bezier(.16,1,.3,1), opacity .25s ease;
}

@media (prefers-reduced-motion: reduce) {
  .hero-cta-row,
  .hero-cta-shine,
  .hero-cta-arrow {
    animation: none !important;
  }
}

/* Premium empty-cart state */
@keyframes empty-cart-enter {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes empty-cart-float {
  0%, 100% { transform: translateY(0) rotate(-1deg); }
  50% { transform: translateY(-8px) rotate(1deg); }
}
@keyframes empty-cart-orbit {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
@keyframes empty-cart-category-in {
  from { opacity: 0; transform: translateY(12px) scale(0.97); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.empty-cart-enter {
  animation: empty-cart-enter 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.empty-cart-icon {
  animation: empty-cart-float 4s 0.6s ease-in-out infinite;
}
.empty-cart-orbit {
  background: conic-gradient(from 90deg, transparent 0 74%, rgba(62,207,76,0.18) 82%, transparent 90%);
  animation: empty-cart-orbit 14s linear infinite;
}
.empty-cart-category {
  opacity: 0;
  animation: empty-cart-category-in 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

@media (prefers-reduced-motion: reduce) {
  .empty-cart-enter,
  .empty-cart-icon,
  .empty-cart-orbit,
  .empty-cart-category {
    animation: none;
  }
  .empty-cart-category { opacity: 1; }
}

/* Order tracking route card */
@keyframes tracking-card-enter {
  from { opacity: 0; transform: translateY(18px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes tracking-route-draw {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
@keyframes tracking-step-enter {
  from { opacity: 0; transform: translateY(8px) scale(0.82); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes tracking-dot-confirmed {
  0%, 100% { box-shadow: 0 0 0 5px rgba(62, 207, 76, 0.12); }
  45% { box-shadow: 0 0 0 10px rgba(62, 207, 76, 0); }
}
@keyframes tracking-truck-glide {
  0%, 100% { transform: translateX(0); }
  50% { transform: translateX(3px); }
}
@keyframes tracking-image-enter {
  from { opacity: 0; transform: translateY(24px); clip-path: inset(0 0 18% 0); }
  to { opacity: 1; transform: translateY(0); clip-path: inset(0 0 0 0); }
}
@keyframes tracking-backdrop-enter {
  from { opacity: 0; transform: scale(1.035) translateX(18px); }
  to { opacity: 1; transform: scale(1) translateX(0); }
}
@keyframes tracking-result-enter {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes tracking-timeline-fill {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}
@keyframes tracking-timeline-step-in {
  from { opacity: 0; transform: translateY(12px) scale(0.9); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes tracking-timeline-check-draw {
  from { stroke-dashoffset: 28; }
  to { stroke-dashoffset: 0; }
}
@keyframes tracking-timeline-latest-pulse {
  0%, 100% { box-shadow: 0 0 0 6px rgba(62, 207, 76, 0.1); }
  50% { box-shadow: 0 0 0 11px rgba(62, 207, 76, 0); }
}
@keyframes tracking-timeline-spark-pulse {
  0%, 100% { opacity: 0.7; transform: translateY(-50%) scale(0.8); }
  50% { opacity: 1; transform: translateY(-50%) scale(1.15); }
}
@keyframes tracking-delivered-note-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes tracking-product-row-in {
  from { opacity: 0; transform: translateX(-12px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes tracking-order-total-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
@keyframes tracking-order-total-sheen {
  0%, 65% { transform: translateX(-180%) skewX(-18deg); opacity: 0; }
  72% { opacity: 0.16; }
  90%, 100% { transform: translateX(520%) skewX(-18deg); opacity: 0; }
}
@keyframes tracking-info-card-in {
  from { opacity: 0; transform: translateX(12px); }
  to { opacity: 1; transform: translateX(0); }
}
@keyframes tracking-info-row-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.tracking-route-card {
  animation: tracking-card-enter 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.tracking-route-line {
  transform: scaleX(0);
  transform-origin: left center;
  animation: tracking-route-draw 0.9s 0.2s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.tracking-route-line > span {
  width: 8%;
}
.tracking-route-step {
  opacity: 0;
  animation: tracking-step-enter 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
.tracking-route-dot--active {
  animation: tracking-dot-confirmed 2.6s 1.2s ease-out infinite;
}
.tracking-route-truck {
  animation: tracking-truck-glide 2.4s 1s ease-in-out infinite;
}
.tracking-delivery-image {
  animation: tracking-image-enter 0.9s 0.15s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.tracking-delivery-backdrop {
  -webkit-mask-image: radial-gradient(ellipse 72% 78% at 62% 54%, #000 18%, rgba(0, 0, 0, 0.82) 52%, transparent 100%);
  mask-image: radial-gradient(ellipse 72% 78% at 62% 54%, #000 18%, rgba(0, 0, 0, 0.82) 52%, transparent 100%);
  animation: tracking-backdrop-enter 1.25s 0.1s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.tracking-delivery-backdrop-right {
  -webkit-mask-image: radial-gradient(ellipse 52% 72% at 76% 52%, #000 0%, rgba(0, 0, 0, 0.92) 38%, transparent 78%);
  mask-image: radial-gradient(ellipse 52% 72% at 76% 52%, #000 0%, rgba(0, 0, 0, 0.92) 38%, transparent 78%);
}
.tracking-delivery-backdrop-courier {
