/* ── Cinematic 3D homepage hero ────────────────────────────────── */
.hero-cinema {
  --hero-x: 0px;
  --hero-y: 0px;
  --hero-rx: 0deg;
  --hero-ry: 0deg;
  --hero-copy-x: 0px;
  --hero-copy-y: 0px;
  isolation: isolate;
  perspective: 1400px;
}

.hero-3d-stage {
  perspective: 1400px;
  transform-style: preserve-3d;
}

.hero-fill-backdrop {
  opacity: .42;
  filter: blur(16px) saturate(.82) brightness(.72);
  transform: scale(1.04);
}

.hero-3d-camera {
  transform: translate3d(var(--hero-x), var(--hero-y), 0) rotateX(var(--hero-rx)) rotateY(var(--hero-ry)) scale(1.01);
  transform-style: preserve-3d;
  transition: transform 700ms cubic-bezier(.16,1,.3,1);
  will-change: transform;
}

@keyframes hero-cinematic-camera {
  0% { opacity: 0; transform: scale(1); filter: saturate(.88) contrast(1.03); }
  12% { opacity: 1; }
  55% { transform: scale(1); filter: saturate(1) contrast(1.04); }
  100% { opacity: 1; transform: scale(1); filter: saturate(1.04) contrast(1.05); }
}

.hero-cinematic-image {
  animation: none;
  transform-origin: center center;
}

.hero-copy-3d {
  transform: translate3d(var(--hero-copy-x), var(--hero-copy-y), 80px);
  transform-style: preserve-3d;
  transition: transform 700ms cubic-bezier(.16,1,.3,1);
  will-change: transform;
}

@keyframes hero-3d-copy-in {
  from { opacity: 0; transform: translate3d(-36px, 48px, 120px) rotateX(-8deg); filter: blur(9px); }
  to { opacity: 1; transform: translate3d(0, 0, 0) rotateX(0); filter: blur(0); }
}

.hero-cinema .hero-eyebrow { animation: hero-3d-copy-in .8s cubic-bezier(.16,1,.3,1) .12s both; }
.hero-cinema .hero-headline,
.hero-cinema .hero-sub,
.hero-cinema .hero-ctas { animation: none; }
.hero-cinema .hero-divider { animation: hero-line-in .9s cubic-bezier(.16,1,.3,1) .55s both; }

.hero-depth-grid {
  z-index: 1;
  opacity: .15;
  background-image: linear-gradient(rgba(62,207,76,.16) 1px, transparent 1px), linear-gradient(90deg, rgba(62,207,76,.12) 1px, transparent 1px);
  background-size: 58px 58px;
  mask-image: linear-gradient(to top, black, transparent 82%);
  transform: perspective(650px) rotateX(66deg) scaleX(1.35) translateY(32%);
  transform-origin: bottom;
}

@keyframes hero-orb-drift {
  0%, 100% { opacity: .18; transform: translate3d(0, 0, 80px) scale(1); }
  50% { opacity: .3; transform: translate3d(-7%, 9%, 120px) scale(1.12); }
}

.hero-light-orb {
  z-index: 1;
  background: radial-gradient(circle, rgba(62,207,76,.52) 0%, rgba(62,207,76,.13) 34%, transparent 70%);
  filter: blur(55px);
  mix-blend-mode: screen;
  animation: hero-orb-drift 7s ease-in-out infinite;
}

@keyframes hero-light-pass {
  0%, 12% { opacity: 0; transform: translate3d(-120%, 0, 120px) skewX(-18deg); }
  28% { opacity: .2; }
  48%, 100% { opacity: 0; transform: translate3d(760%, 0, 120px) skewX(-18deg); }
}

.hero-light-sweep {
  z-index: 4;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.45), transparent);
  filter: blur(16px);
  mix-blend-mode: soft-light;
  animation: hero-light-pass 8s ease-in-out 1s infinite;
}

@keyframes hero-grain-shift {
  0%, 100% { transform: translate3d(0,0,0); }
  25% { transform: translate3d(-1.5%,1%,0); }
  50% { transform: translate3d(1%,-1.5%,0); }
  75% { transform: translate3d(.8%,1.2%,0); }
}

.hero-film-grain {
  z-index: 5;
  inset: -8%;
  pointer-events: none;
  opacity: .055;
  background-image: repeating-radial-gradient(circle at 30% 40%, rgba(255,255,255,.9) 0 .6px, transparent .8px 3.4px);
  background-size: 7px 7px;
  mix-blend-mode: overlay;
  animation: hero-grain-shift .55s steps(2, end) infinite;
}

.hero-vignette {
  z-index: 6;
  pointer-events: none;
  box-shadow: inset 0 0 130px rgba(0,0,0,.32), inset 0 -80px 110px rgba(0,0,0,.28);
}

@keyframes hero-slide-progress {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

.hero-slide-progress { animation: hero-slide-progress 7s linear both; }
.hero-cinema.is-paused .hero-slide-progress { animation-play-state: paused; }

@media (max-width: 767px) {
  .hero-3d-camera { transform: scale(1.005); }
  .hero-cinematic-image { animation-duration: 10s; }
  .hero-film-grain { opacity: .035; }
  .hero-vignette { box-shadow: inset 0 -90px 120px rgba(0,0,0,.34); }
  .hero-copy-3d { transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .hero-3d-camera,
  .hero-copy-3d { transform: none !important; transition: none !important; }
  .hero-cinematic-image,
  .hero-cinema .hero-eyebrow,
  .hero-cinema .hero-headline,
  .hero-cinema .hero-sub,
  .hero-cinema .hero-ctas,
  .hero-cinema .hero-divider,
  .hero-light-orb,
  .hero-light-sweep,
  .hero-film-grain,
  .hero-slide-progress { animation: none !important; }
}

@keyframes product-summary-enter {
  from { opacity: 0; transform: translateY(12px); filter: blur(3px); }
  to { opacity: 1; transform: translateY(0); filter: blur(0); }
}

@keyframes product-spec-enter {
  from { opacity: 0; transform: translateY(8px) scale(.96); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.product-summary-enter {
  animation: product-summary-enter .65s cubic-bezier(.16,1,.3,1) both;
}

.product-spec-chip {
  animation: product-spec-enter .55s cubic-bezier(.16,1,.3,1) both;
}

@media (prefers-reduced-motion: reduce) {
  .product-summary-enter,
  .product-spec-chip {
    animation: none !important;
  }
}
.hero-divider  {
  display: block;
  height: 2px;
  background: white;
  transform-origin: left;
  animation: hero-line-in 0.6s cubic-bezier(0.22,1,0.36,1) 0.3s both;
}

/* ── Logo animations ──────────────────────────────────────────────── */
@keyframes logo-bar-in {
  0%   { opacity: 0; transform: translateY(12px) scaleY(0.6); }
  60%  { transform: translateY(-3px) scaleY(1.04); }
  80%  { transform: translateY(1px) scaleY(0.98); }
  100% { opacity: 1; transform: translateY(0) scaleY(1); }
}
@keyframes logo-dot-in {
  0%   { opacity: 0; transform: scale(0) translateY(4px); }
  70%  { transform: scale(1.4) translateY(-1px); }
  100% { opacity: 1; transform: scale(1) translateY(0); }
}
@keyframes logo-text-in {
  0%   { opacity: 0; transform: translateX(-10px) skewX(-4deg); filter: blur(4px); }
  100% { opacity: 1; transform: translateX(0) skewX(0); filter: blur(0); }
}
@keyframes logo-sweep {
  0%, 65%  { transform: translateX(-120%) skewX(-20deg); opacity: 0; }
  68%      { opacity: 1; }
  88%      { transform: translateX(520%) skewX(-20deg); opacity: 0.6; }
  100%     { transform: translateX(520%) skewX(-20deg); opacity: 0; }
}

/* ── Trust badge pulse ──────────────────────────────────────────── */
@keyframes trust-in {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ── Scroll Reveal System ──────────────────────────────────────────── */
.sr {
  opacity: 1;
  transition:
    opacity 0.25s ease,
    transform 0.25s ease;
}
.sr-pending { opacity: 0; }
.sr-pending.sr-up    { transform: translateY(12px); }
.sr-pending.sr-left  { transform: translateX(-12px); }
.sr-pending.sr-right { transform: translateX(12px); }
.sr-pending.sr-scale { transform: scale(0.98); }

.sr.in {
  opacity: 1;
  transform: none;
  filter: none;
}

/* Product rails remain visible before hydration and when JavaScript fails. */
.card-sr { opacity: 1; }

/* Accent line reveal */
@keyframes line-in {
  from { transform: scaleX(0); opacity: 0; }
  to   { transform: scaleX(1); opacity: 1; }
}
.sr-line {
  transform-origin: left;
  opacity: 0;
}
.sr-line.in {
  animation: line-in 0.55s cubic-bezier(0.16, 1, 0.3, 1) 0.1s both;
}

/* ── Hero image entrance ──────────────────────────────────────────── */
@keyframes hero-image-entrance {
  from { opacity: 0; transform: scale(1.04); }
  to   { opacity: 1; transform: scale(1); }
}
.hero-image-entrance {
  animation: hero-image-entrance 1.6s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* ── Shimmer card sweep ────────────────────────────────────────────── */
@keyframes shimmer-sweep {
  from { transform: translateX(-110%) skewX(-12deg); }
  to   { transform: translateX(220%)  skewX(-12deg); }
}
.shimmer-on-hover {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.shimmer-on-hover::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(255,255,255,0.14) 50%, transparent 100%);
  transform: translateX(-110%) skewX(-12deg);
  transition: none;
}
.group:hover .shimmer-on-hover::after {
  animation: shimmer-sweep 0.65s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

/* ── Number count-up glow ─────────────────────────────────────────── */
@keyframes stat-value-in {
  from { opacity: 0; transform: translateY(14px) scale(0.92); }
  to   { opacity: 1; transform: translateY(0)    scale(1); }
}
.stat-value-in {
  animation: stat-value-in 0.7s cubic-bezier(0.16, 1, 0.3, 1) both;
}

/* ── Products load-more magic ────────────────────────────────────── */
@keyframes load-more-breathe {
  0%, 100% { opacity: 0.18; transform: scale(0.88); }
  50%      { opacity: 0.42; transform: scale(1.08); }
}
@keyframes load-more-sweep {
  0%, 68%  { transform: translateX(-180%) skewX(-18deg); opacity: 0; }
  72%      { opacity: 0.55; }
  88%, 100% { transform: translateX(340%) skewX(-18deg); opacity: 0; }
}
@keyframes load-more-arrow-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(2px); }
}
.magic-load-more::before {
  content: "";
  position: absolute;
  right: 20px;
  top: 50%;
  width: 40px;
  height: 40px;
  margin-top: -20px;
  border-radius: 999px;
  background: rgba(62, 207, 76, 0.32);
  filter: blur(10px);
  animation: load-more-breathe 3s ease-in-out infinite;
}
.magic-load-more__glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(105deg, rgba(62, 207, 76, 0.035), transparent 42%);
  opacity: 0.7;
  transition: opacity 0.35s ease;
}
.magic-load-more__sweep {
  position: absolute;
  inset: -20% auto -20% 0;
  width: 26%;
  pointer-events: none;
  background: linear-gradient(90deg, transparent, rgba(62, 207, 76, 0.07), rgba(255,255,255,0.9), transparent);
  animation: load-more-sweep 5s cubic-bezier(0.16, 1, 0.3, 1) infinite;
}
.magic-load-more__arrow {
  animation: load-more-arrow-float 1.8s ease-in-out infinite;
}
.magic-load-more:hover .magic-load-more__glow { opacity: 1; }
.magic-load-more:hover .magic-load-more__arrow { animation-duration: 0.85s; }

@media (prefers-reduced-motion: reduce) {
  .magic-load-more::before,
  .magic-load-more__sweep,
  .magic-load-more__arrow {
    animation: none;
  }
}

/* Chat launcher: a gentle arrival and a short, quiet invitation every 14 seconds. */
@keyframes eco-chat-enter {
  from { opacity: 0; transform: translateY(16px) scale(0.94); }
  70% { opacity: 1; transform: translateY(-2px) scale(1.01); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes eco-chat-pulse {
  0%, 14%, 100% { opacity: 0; transform: scale(1); }
  2% { opacity: 0.3; transform: scale(1); }
  12% { opacity: 0; transform: scale(1.35); }
}
@keyframes eco-chat-icon-nudge {
  0%, 12%, 100% { transform: translateY(0) rotate(0); }
  3% { transform: translateY(-1px) rotate(-9deg); }
  6% { transform: translateY(-1px) rotate(6deg); }
  9% { transform: translateY(0) rotate(-3deg); }
}
/* Keep assistance clear of the size menu; restore it as soon as the menu closes. */
body:has([data-size-select-open="true"]) .eco-chat-launcher {
  display: none;
}

.eco-chat-launcher {
  animation: eco-chat-enter 800ms cubic-bezier(0.22, 1, 0.36, 1) backwards;
  box-shadow: 0 4px 16px rgb(24 60 48 / 9%);
  transition: transform 200ms ease, border-color 200ms ease, box-shadow 200ms ease;
}
.eco-chat-launcher-icon {
  position: relative;
  display: inline-flex;
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: #183c30;
  color: #fff;
  transition: transform 250ms ease, background-color 250ms ease;
}
.eco-chat-launcher-icon::before {
  content: "";
  position: absolute;
  inset: 0;
  border: 1px solid #41785c;
  border-radius: inherit;
  opacity: 0;
  pointer-events: none;
  animation: eco-chat-pulse 14s ease-out 4s infinite;
}
.eco-chat-launcher-icon svg {
  animation: eco-chat-icon-nudge 14s ease-in-out 4s infinite;
  transform-origin: 50% 70%;
}
@media (hover: hover) {
  .eco-chat-launcher:hover { transform: translateY(-2px); border-color: #bdcdb6; box-shadow: 0 6px 20px rgb(24 60 48 / 13%); }
  .eco-chat-launcher:hover .eco-chat-launcher-icon { transform: rotate(-6deg); background: #28533f; }
  .eco-chat-launcher:hover .eco-chat-launcher-icon::before,
  .eco-chat-launcher:hover .eco-chat-launcher-icon svg { animation-play-state: paused; }
}
.eco-chat-launcher:active { transform: translateY(0) scale(0.97); }
@media (prefers-reduced-motion: reduce) {
  .eco-chat-launcher,
  .eco-chat-launcher-icon::before,
  .eco-chat-launcher-icon svg,
  .eco-chat-launcher-icon { animation: none; transition: none; }
  .eco-chat-launcher:hover .eco-chat-launcher-icon,
  .eco-chat-launcher:hover,
  .eco-chat-launcher:active { transform: none; }
}
